    "bookName": "1 Chronicles",
    "chapterNumber": 3,
    "title": "1 Chronicles 3: Royal House of David Across Hebron & Exile",
    "subtitle": "Traces David’s sons in Hebron and Jerusalem, through Solomon and Josiah, onward into exile and hope.",
    "summaryHook": "Traces David’s sons in Hebron and Jerusalem, through Solomon and Josiah, onward into exile and hope.",
    "bigPictureText": "Even when Jerusalem’s throne lies silent in Babylon, Chronicles keeps counting David’s heirs—trusting God’s everlasting covenant word.",
    "illustrationTheme": "ill-1ch-3",
    "illustrationId": "ill-1ch-3",
