        "bookName": "1 Chronicles",
        "chapterNumber": 3,
        "verseNumber": 5,
        "text": "and these were born to him in Jerusalem: Shimea, Shobab, Nathan, and Solomon, four, of Bathshua the daughter of Ammiel;",
        "translation": "WEB",
