        "bookName": "1 Chronicles",
        "chapterNumber": 3,
        "verseNumber": 6,
        "text": "and Ibhar, Elishama, Eliphelet,",
        "translation": "WEB",
        "illustrationId": "ill-1ch-3",
        "linkedEntities": []
