    "title": "1 Chronicles 15: Sacred Ark Carried on Levites’ Shoulders With Praise",
    "subtitle": "“Because we didn’t seek Him according to the ordinance before”—now Zadok, Heman, Asaph, and Jeduthun lift joyful cymbals.",
    "summaryHook": "“Because we didn’t seek Him according to the ordinance before”—now Zadok, Heman, Asaph, and Jeduthun lift joyful cymbals.",
