        "bookId": "1CH",
        "bookName": "1 Chronicles",
        "chapterNumber": 24,
        "verseNumber": 7,
        "text": "Now the first lot came out to Jehoiarib, the second to Jedaiah,",
        "translation": "WEB",
        "illustrationId": "ill-1ch-24",
        "linkedEntities": []
