        "bookId": "1CH",
        "bookName": "1 Chronicles",
        "chapterNumber": 26,
        "verseNumber": 22,
        "text": "The sons of Jehieli: Zetham, and Joel his brother, over the treasures of Yahweh’s house.",
        "translation": "WEB",
        "illustrationId": "ill-1ch-26",
        "linkedEntities": [
          {
            "spanText": "Yahweh",
            "entityId": "term-yahweh"
          }
        ]
